-- SECTIONS master (below DEPARTMENTS) from NILEPET_HR_Organizational_Master_Data.xlsx, sheet Sections. Dev data, proposed/mock structure.
-- Creates table + sequence if missing, then loads 244 sections. Run once (CREATE is not idempotent; the inserts skip existing codes). Undo: db/create_sections_nilepet_rollback.sql
SET DEFINE OFF;

CREATE SEQUENCE HRMS.SEQ_SECTIONS INCREMENT BY 1 MINVALUE 1 MAXVALUE 999999999 NOCYCLE NOCACHE NOORDER;

CREATE TABLE HRMS.SECTIONS (
	SECTION_ID NUMBER(20,0) NOT NULL,
	DEPT_ID NUMBER(20,0) NOT NULL,
	SECTION_CODE VARCHAR2(30) NOT NULL,
	SECTION_NAME VARCHAR2(200) NOT NULL,
	SECTION_NAME_AR NVARCHAR2(200) NOT NULL,
	IS_ACTIVE NUMBER(1,0) DEFAULT 1 NOT NULL,
	CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
	UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
	VERSION NUMBER(10,0) DEFAULT 0 NOT NULL,
	CONSTRAINT PK_SECTIONS PRIMARY KEY (SECTION_ID),
	CONSTRAINT UQ_SECTIONS_CODE UNIQUE (SECTION_CODE),
	CONSTRAINT FK_SECTIONS_DEPT_ID FOREIGN KEY (DEPT_ID) REFERENCES HRMS.DEPARTMENTS(DEPT_ID),
	CONSTRAINT CHK_SECTIONS_ACTIVE CHECK (IS_ACTIVE IN (0,1))
);
CREATE INDEX IDX_SECTIONS_DEPT_ID ON HRMS.SECTIONS (DEPT_ID);

